import numpy as np
def transform(g):
    a=[row[:] for row in g]; H,W=len(a),len(a[0])
    cnt=Counter(x for r in a for x in r); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if a[i][j]!=bg and not seen[i][j]:
                col=a[i][j]; stack=[(i,j)]; comp=[]; seen[i][j]=True
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and a[ny][nx]==col:
                            seen[ny][nx]=True; stack.append((ny,nx))
                ys=[c[0] for c in comp]; xs=[c[1] for c in comp]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                # full rectangle border check
                expect={(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1)
                        if y in(y0,y1) or x in(x0,x1)}
                if set(comp)==expect and y1>y0 and x1>x0:
                    area=(y1-y0-1)*(x1-x0-1)
                    fill=2 if area%2==0 else 7
                    for y in range(y0+1,y1):
                        for x in range(x0+1,x1): a[y][x]=fill
    return a
